// Event-driven auto-dismiss for Station Mismatch Dialog
(function() {
    var dialogObserver = new MutationObserver(function(mutations) {
        var hasNewNodes = false;
        for (var i = 0; i < mutations.length; i++) {
            if (mutations[i].addedNodes.length > 0) {
                hasNewNodes = true;
                break;
            }
        }
        
        if (hasNewNodes) {
            // Check for Station Mismatch Dialog
            var msg = document.querySelector('.ui-confirmdialog-message');
            if (msg && msg.textContent.includes('but booking from') && msg.textContent.includes('Do you want to continue')) {
                var btn = document.querySelector('.ui-confirmdialog-acceptbutton');
                if (btn && !btn.disabled && btn.offsetParent !== null) {
                    btn.click();
                    console.log('[IRCTC-Bot] Event-driven auto-clicked Yes on station mismatch dialog.');
                }
            }
            
            // Check for Last Transaction Detail Dialog
            var txnTitles = document.querySelectorAll('.ui-dialog-title');
            for (var k = 0; k < txnTitles.length; k++) {
                if (txnTitles[k].textContent.includes('Last Transaction Detail')) {
                    var txnDialog = txnTitles[k].closest('.ui-dialog');
                    if (txnDialog) {
                        var closeBtns = txnDialog.querySelectorAll('button');
                        var closeBtn = null;
                        for (var j = 0; j < closeBtns.length; j++) {
                            if (closeBtns[j].getAttribute('aria-label') === 'Close. Last Transaction Detail popup.' || 
                                closeBtns[j].textContent.trim().toLowerCase() === 'close') {
                                closeBtn = closeBtns[j];
                                break;
                            }
                        }
                        if (closeBtn && !closeBtn.disabled && closeBtn.offsetParent !== null) {
                            closeBtn.click();
                            console.log('[IRCTC-Bot] Event-driven auto-clicked Close on Last Transaction Detail dialog.');
                        }
                    }
                }
            }
            
            // Check for High Load Toast on non-Train List pages
            var tst = document.querySelector('.ui-toast-detail');
            if (tst && tst.textContent.toLowerCase().includes('high load')) {
                if (!document.querySelector('app-train-list')) {
                    var cls = document.querySelector('.ui-toast-close-icon');
                    if (cls) cls.click();
                    chrome.storage.local.get("tatkalTicketBookingFormData", function(data) {
                        var retryTime = 300;
                        if (data && data.tatkalTicketBookingFormData && typeof data.tatkalTicketBookingFormData.refreshTime === 'number') {
                            retryTime = data.tatkalTicketBookingFormData.refreshTime;
                        }
                        setTimeout(function() {
                            if (document.querySelector('app-passenger-input')) {
                                var btn = document.querySelector('app-passenger-input button.btnDefault.train_Search');
                                if (btn && !btn.disabled) { btn.click(); console.log('[IRCTC-Bot] Auto-retried Continue on Passenger Page.'); }
                            } else if (document.querySelector('app-review-booking')) {
                                var btn = document.querySelector('app-review-booking button.btnDefault.train_Search');
                                if (btn && !btn.disabled) { btn.click(); console.log('[IRCTC-Bot] Auto-retried Continue on Review Page.'); }
                            } else if (document.querySelector('app-payment-options')) {
                                var btn = document.querySelector('button.btn-primary.ng-star-inserted');
                                if (btn && btn.textContent.includes('Pay & Book') && !btn.disabled) {
                                    btn.click(); console.log('[IRCTC-Bot] Auto-retried Pay & Book.');
                                } else {
                                    var ebtn = document.querySelector('app-ewallet-confirm button.mob-bot-btn.search_btn');
                                    if (ebtn && ebtn.textContent.includes('CONFIRM') && !ebtn.disabled) {
                                        ebtn.click(); console.log('[IRCTC-Bot] Auto-retried eWallet Confirm.');
                                    }
                                }
                            }
                        }, retryTime);
                    });
                }
            }
        }
    });
    
    // Start observing the document body for injected dialogs
    if (document.body) {
        dialogObserver.observe(document.body, { childList: true, subtree: true });
    } else {
        document.addEventListener('DOMContentLoaded', function() {
            dialogObserver.observe(document.body, { childList: true, subtree: true });
        });
    }
})();
